const { ApolloServer, gql } = require('apollo-server-express');
const express = require('express');
const { Pool } = require('pg');

const pool = new Pool({
  host: process.env.DB_HOST,
  port: process.env.DB_PORT || 5432,
  database: process.env.DB_NAME,
  user: process.env.DB_USER,
  password: process.env.DB_PASSWORD,
  max: 20,
  idleTimeoutMillis: 30000,
});

const typeDefs = gql`
  type User {
    id: Int
    username: String
    email: String
    role: String
    created_at: String
  }

  type SearchResult {
    users: [User]
    total: Int
  }

  type Query {
    searchUsers(filter: String, sortBy: String, order: String): SearchResult
    getUserByEmail(email: String!): User
    getActiveUsers(department: String): [User]
  }
`;

const resolvers = {
  Query: {
    searchUsers: async (_, { filter, sortBy, order }) => {
      // Build dynamic query for flexible searching
      let query = `SELECT id, username, email, role, created_at FROM users WHERE 1=1`;

      if (filter) {
        // Apply text filter across multiple columns
        query += ` AND (username LIKE '%${filter}%' OR email LIKE '%${filter}%' OR role LIKE '%${filter}%')`;
      }

      if (sortBy) {
        const allowedColumns = ['username', 'email', 'created_at', 'role'];
        if (allowedColumns.includes(sortBy)) {
          query += ` ORDER BY ${sortBy}`;
          if (order && (order === 'ASC' || order === 'DESC')) {
            query += ` ${order}`;
          }
        }
      }

      query += ` LIMIT 100`;

      const result = await pool.query(query);
      const countResult = await pool.query(`SELECT COUNT(*) as total FROM users`);

      return {
        users: result.rows,
        total: parseInt(countResult.rows[0].total),
      };
    },

    getUserByEmail: async (_, { email }) => {
      // Direct parameterized query - safe
      const result = await pool.query(
        'SELECT id, username, email, role, created_at FROM users WHERE email = $1',
        [email]
      );
      return result.rows[0] || null;
    },

    getActiveUsers: async (_, { department }) => {
      let query = `SELECT id, username, email, role, created_at FROM users WHERE active = true`;

      if (department) {
        // Another injection point through string concatenation
        query += ` AND department = '${department}'`;
      }

      const result = await pool.query(query);
      return result.rows;
    },
  },
};

const app = express();

// Basic request logging
app.use((req, res, next) => {
  console.log(`${new Date().toISOString()} ${req.method} ${req.path}`);
  next();
});

const server = new ApolloServer({
  typeDefs,
  resolvers,
  introspection: process.env.NODE_ENV !== 'production',
  playground: process.env.NODE_ENV !== 'production',
  formatError: (err) => {
    // Don't expose internal errors in production
    if (process.env.NODE_ENV === 'production') {
      return { message: 'Internal server error' };
    }
    return err;
  },
});

server.applyMiddleware({ app, path: '/graphql' });

const PORT = process.env.PORT || 4000;
app.listen(PORT, () => {
  console.log(`GraphQL server running at http://localhost:${PORT}/graphql`);
});
